42	func newPRTBHandler(uc *config.UserContext) (*prtbHandler, error) {
43		impersonator, err := impersonation.ForCluster(uc)
44		if err != nil {
45			return nil, err
46		}
47		return &prtbHandler{
48			impersonationHandler: impersonationHandler{
49				clusterName:  uc.ClusterName,
50				impersonator: impersonator,
51				crClient:     uc.RBACw.ClusterRole(),
52				crtbCache:    uc.Management.Wrangler.Mgmt.ClusterRoleTemplateBinding().Cache(),
53				prtbCache:    uc.Management.Wrangler.Mgmt.ProjectRoleTemplateBinding().Cache(),
54			},
55			crClient:    uc.RBACw.ClusterRole(),
56			crbClient:   uc.RBACw.ClusterRoleBinding(),
57			rtClient:    uc.Management.Wrangler.Mgmt.RoleTemplate(),
58			nsClient:    uc.Corew.Namespace(),
59			rbClient:    uc.RBACw.RoleBinding(),
60			clusterName: uc.ClusterName,
61		}, nil
62	}
