64	// OnChange ensures a Role Binding exists in every project namespace to the RoleTemplate ClusterRole.
65	// If there are promoted rules, it creates a second Role Binding in each namespace to the promoted ClusterRole
66	func (p *prtbHandler) OnChange(_ string, prtb *v3.ProjectRoleTemplateBinding) (*v3.ProjectRoleTemplateBinding, error) {
67		if prtb == nil || prtb.DeletionTimestamp != nil || !features.AggregatedRoleTemplates.Enabled() {
68			return nil, nil
69		}
70	
71		// Only run this controller if the PRTB is for this cluster
72		clusterName, _ := rbac.GetClusterAndProjectNameFromPRTB(prtb)
73		if clusterName != p.clusterName {
74			return nil, nil
75		}
76	
77		// Create bindings
78		if err := errors.Join(p.reconcileClusterRoleBindings(prtb), p.reconcileBindings(prtb)); err != nil {
79			return nil, err
80		}
81	
82		// Ensure a service account impersonator exists on the cluster.
83		if prtb.UserName != "" {
84			if err := p.impersonationHandler.ensureServiceAccountImpersonator(prtb.UserName); err != nil {
85				return nil, fmt.Errorf("error ensuring service account impersonator for %s: %w", prtb.UserName, err)
86			}
87		}
88	
89		return prtb, nil
90	}
91	
92	// reconcileBindings lists all existing RoleBindings in each project namespace and ensures they are correct.
93	// If not it deletes them and creates the correct RoleBindings.
94	func (p *prtbHandler) reconcileBindings(prtb *v3.ProjectRoleTemplateBinding) error {
95		subject, err := rbac.BuildSubjectFromRTB(prtb)
96		if err != nil {
97			return err
98		}
99	
100		isExternal, err := isRoleTemplateExternal(prtb.RoleTemplateName, p.rtClient)
101		if err != nil {
102			return err
103		}
104	
105		// External Role Templates don't support aggregation, bind to the external cluster role directly.
106		var roleName string
107		if isExternal {
108			roleName = prtb.RoleTemplateName
109		} else {
110			roleName = rbac.AggregatedClusterRoleNameFor(prtb.RoleTemplateName)
111		}
112	
113		roleRef := rbacv1.RoleRef{
114			Kind:     "ClusterRole",
115			Name:     roleName,
116			APIGroup: rbacv1.GroupName,
117		}
118	
119		namespaces, err := p.getNamespacesFromProject(prtb)
120		if err != nil {
121			return err
122		}
123	
124		for _, namespace := range namespaces.Items {
125			if !namespace.DeletionTimestamp.IsZero() {
126				continue
127			}
128	
129			rb := &rbacv1.RoleBinding{
130				ObjectMeta: metav1.ObjectMeta{
131					Name: rbac.NameForRoleBinding(namespace.Name, roleRef, subject),
132					Labels: map[string]string{
133						rbac.GetPRTBOwnerLabel(prtb.Name): "true",
134						rbac.AggregationFeatureLabel:      "true",
135					},
136					Namespace: namespace.Name,
137				},
138				RoleRef:  roleRef,
139				Subjects: []rbacv1.Subject{subject},
140			}
141	
142			if err := p.ensureOnlyDesiredRoleBindingExists(rb, rbac.GetPRTBOwnerLabel(prtb.Name), rbac.GetRTBLabel(prtb.ObjectMeta)); err != nil {
143				return err
144			}
145		}
146	
147		return nil
148	}
