150	// reconcileClusterRoleBindings handles the promoted and namespace Cluster Role Bindings for a PRTB.
151	// Promoted CRBs are for any rules that are non-namespace scoped that are given by the PRTB.
152	// Namespace CRBs are to give the user either edit or read-only access to the namespaces within the project. Primarily used by the UI.
153	func (p *prtbHandler) reconcileClusterRoleBindings(prtb *v3.ProjectRoleTemplateBinding) error {
154		crbs := []*rbacv1.ClusterRoleBinding{}
155	
156		// If the RoleTemplate doesn't exist yet, there's no way to tell if Promoted or Namespace Rules exist
157		rt, err := p.rtClient.Get(prtb.RoleTemplateName, metav1.GetOptions{})
158		if apierrors.IsNotFound(err) {
159			return nil
160		} else if err != nil {
161			return err
162		}
163	
164		// Check for promoted rules.
165		hasPromotedRule, err := p.doesRoleTemplateHavePromotedRules(rt)
166		if err != nil {
167			return err
168		}
169		if hasPromotedRule {
170			promotedRuleName := rbac.PromotedClusterRoleNameFor(prtb.RoleTemplateName)
171			crb, err := rbac.BuildAggregatingClusterRoleBindingFromRTB(prtb, promotedRuleName)
172			if err != nil {
173				return err
174			}
175			crbs = append(crbs, crb)
176		}
177	
178		// Namespace rules always need to be created.
179		namespaceCRBs, err := p.buildNamespaceBindings(prtb)
180		if err != nil {
181			return err
182		}
183	
184		crbs = append(crbs, namespaceCRBs...)
185	
186		return p.ensureOnlyDesiredClusterRoleBindingsExists(crbs, rbac.GetPRTBOwnerLabel(prtb.Name), rbac.GetRTBLabel(prtb.ObjectMeta))
187	}
