155	func (c *crtbHandler) updateStatus(crtb *v3.ClusterRoleTemplateBinding, remoteConditions []metav1.Condition) error {
156		return retry.RetryOnConflict(retry.DefaultRetry, func() error {
157			crtbFromCluster, err := c.crtbCache.Get(crtb.Namespace, crtb.Name)
158			if err != nil {
159				return err
160			}
161			if status.CompareConditions(crtbFromCluster.Status.RemoteConditions, remoteConditions) {
162				return nil
163			}
164	
165			crtbFromCluster.Status.SummaryRemote = status.SummaryCompleted
166			if crtbFromCluster.Status.SummaryLocal == status.SummaryCompleted {
167				crtbFromCluster.Status.Summary = status.SummaryCompleted
168			}
169			for _, c := range remoteConditions {
170				if c.Status != metav1.ConditionTrue {
171					crtbFromCluster.Status.Summary = status.SummaryError
172					crtbFromCluster.Status.SummaryRemote = status.SummaryError
173					break
174				}
175			}
176	
177			crtbFromCluster.Status.LastUpdateTime = timeNow().Format(time.RFC3339)
178			crtbFromCluster.Status.ObservedGenerationRemote = crtb.ObjectMeta.Generation
179			crtbFromCluster.Status.RemoteConditions = remoteConditions
180			_, err = c.crtbClient.UpdateStatus(crtbFromCluster)
181			if err != nil {
182				return err
183			}
184			return nil
185		})
186	}
