265	// ensureOnlyDesiredClusterRoleBindingsExists takes a list of ClusterRoleBindings and ensures they are the only CRBs that exist for this PRTB.
266	// Deletes any CRBs with the prtbOwnerLabel that aren't in the given list.
267	func (p *prtbHandler) ensureOnlyDesiredClusterRoleBindingsExists(crbs []*rbacv1.ClusterRoleBinding, prtb *v3.ProjectRoleTemplateBinding) error {
268		// Turn the slice into a map for easier operations.
269		desiredCRBs := map[string]*rbacv1.ClusterRoleBinding{}
270		for _, crb := range crbs {
271			desiredCRBs[crb.Name] = crb
272		}
273	
274		// Make sure the aggregation label is set on all the desired CRBs so they can be filtered on later.
275		for _, crb := range crbs {
276			AddAggregationFeatureLabel(crb)
277		}
278	
279		labelSelector := labels.Set{
280			rbac.GetPRTBOwnerLabel(prtb.Name): "true",
281			rbac.AggregationFeatureLabel:      "true",
282		}
283		aggregationCRBs, err := p.crbClient.List(metav1.ListOptions{LabelSelector: labelSelector.AsSelector().String()})
284		if err != nil || aggregationCRBs == nil {
285			return err
286		}
287	
288		// Delete any ClusterRoleBindings that were created for this PRTB before the aggregation changes.
289		// TODO: Remove this once roletemplate aggregation is the only enabled RBAC model. https://github.com/rancher/rancher/issues/53743
290		legacyCRBs, err := p.crbClient.List(metav1.ListOptions{LabelSelector: rtbOwnerLabel + "=" + rbac.GetRTBLabel(prtb.ObjectMeta)})
291		if err != nil || legacyCRBs == nil {
292			return err
293		}
294	
295		currentCRBs := append(aggregationCRBs.Items, legacyCRBs.Items...)
296	
297		// Search for the ClusterRoleBindings that are needed, all others should be removed.
298		for _, currentCRB := range currentCRBs {
299			if desiredCRB, ok := desiredCRBs[currentCRB.Name]; ok {
300				if rbac.IsClusterRoleBindingContentSame(&currentCRB, desiredCRB) {
301					delete(desiredCRBs, desiredCRB.Name)
302					continue
303				}
304			}
305			// Subject and RoleRef can't be updated, so we need to delete and recreate them.
306			if err = rbac.DeleteResource(currentCRB.Name, p.crbClient); err != nil {
307				return err
308			}
309		}
310	
311		// Any remaining ClusterRoleBindings in the desiredCRBs get created.
312		for _, crb := range desiredCRBs {
313			// It's possible the CRB was already created, so ignore AlreadyExists errors
314			if _, err := p.crbClient.Create(crb); err != nil && !apierrors.IsAlreadyExists(err) {
315				return fmt.Errorf("failed to create cluster role binding %s: %w", crb.Name, err)
316			}
317		}
318		return nil

